sys_ui_action.script:
try {
    var source = "x_512592_ebondin_0";
    var scriptIncludeName = current.implementation.name;

    // Check is script include exists ...
    var grScriptInclude = new GlideRecord("sys_script_include");
    grScriptInclude.addEncodedQuery("name=" + scriptIncludeName);
    grScriptInclude.query();
    if (!grScriptInclude.next())
        throw "Cannot find Script Include with name: " + scriptIncludeName;


    // Init ebonding config data
    var ebondingConfig = {
        name: current.name.toString(),
        technical_name: current.technical_name.toString(),
        processes: [],
    };

    // Pour chaque process ...
    var grProcess = new GlideRecord("x_512592_ebondin_0_ebondingprocess");
    grProcess.addQuery("ebonding_config", current.getUniqueValue());
    grProcess.query();
    while (grProcess.next()) {

        var process = {
            table_name: grProcess.table_name.toString(),
            inbound_create: (grProcess.inbound_create == true),
            inbound_update: (grProcess.inbound_update == true),
            outbound_create: (grProcess.outbound_create == true),
            outbound_create_url_path: grProcess.outbound_create_url_path.toString(),
            outbound_update: (grProcess.outbound_update == true),
            outbound_update_uri_path: grProcess.outbound_update_uri_path.toString(),
            mappings: [],
        };

        // Pour chaque mapping ...
        var grMapping = new GlideRecord("x_512592_ebondin_0_ebondingmapping");
        grMapping.addQuery("ebonding_process", grProcess.getUniqueValue());
        grMapping.orderBy("order");
        grMapping.query();
        while (grMapping.next()) {
            var mapping = {
                way: grMapping.way.toString(),
                type: grMapping.type.toString(),
                order: grMapping.order.toString(),
                source: grMapping.source.toString(),
                target: grMapping.target.toString(),
                default_value: grMapping.default_value.toString(),
                is_id: (grMapping.is_id == true),
                mandatory: (grMapping.mandatory == true),
                advanced: (grMapping.advanced == true),
                transform_script: grMapping.transform_script.toString(),
            }

            process.mappings.push(mapping);
        }

        ebondingConfig.processes.push(process);
    }

    // Execute script include ...
    new global[scriptIncludeName]()["generate"](source, ebondingConfig);

} catch (e) {
    gs.error("[ERROR] " + e);
}
